    fun getPairsForTopic(topicName: String): List<CuratedTopicPair> {
        return pairs.filter { it.topic.equals(topicName, ignoreCase = true) }
    }

    fun getCountForTopic(topicName: String): Int {
        return pairs.count { it.topic.equals(topicName, ignoreCase = true) }
    }

    fun searchDeclarations(query: String): List<CuratedTopicPair> {
        val q = query.trim().lowercase()
        if (q.isBlank()) return emptyList()
        return pairs.filter { it.declaration.lowercase().contains(q) || it.reference.lowercase().contains(q) }
    }
